# Replace all 4 slides in html
pattern = r'<div class="absolute inset-0 transition-opacity duration-700 ease-in-out[^"]*" data-hero-slide="0".*?id="hero-slide-3">.*?</div></div>'
replacement = f'{new_slide_0}{new_slide_1}{new_slide_2}{new_slide_3}</div>'

# Check if regex matches
m = re.search(pattern, html, flags=re.DOTALL)
if m:
    html = html[:m.start()] + replacement + html[m.end():]
    with open('jewellery-design-html/index.html', 'w', encoding='utf-8') as f:
        f.write(html)
    print("Updated jewellery-design-html/index.html successfully!")
else:
    print("Pattern did not match directly, searching for slide 0 start and slide 3 end...")
    idx0 = html.find('id="hero-slide-0"')
    s0_start = html.rfind('<div class="absolute inset-0', 0, idx0)
    idx3 = html.find('id="hero-slide-3"')
    # find the closing </div> of slide 3
    s3_close = html.find('</div><div class="absolute bottom-4', idx3)
    if s0_start != -1 and s3_close != -1:
        html = html[:s0_start] + f'{new_slide_0}{new_slide_1}{new_slide_2}{new_slide_3}' + html[s3_close:]
        with open('jewellery-design-html/index.html', 'w', encoding='utf-8') as f:
            f.write(html)
        print("Updated via index boundaries in jewellery-design-html/index.html!")
    else:
        print("Failed to find boundaries in index.html!")

